گزارش خرید و تدارکات این ماه را بده: هزینه، انحراف قیمت، و عملکرد تأمین‌کنندگان. (مدیر خرید — شرکت سنگ‌آهن چادرملو)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "purchase_orders",
      "description": "سفارشات خرید به تفکیک تأمین‌کننده و قلم",
      "dimensions": [
        "supplier",
        "item",
        "period"
      ],
      "measures": [
        "quantity",
        "unit_price",
        "total_cost"
      ]
    },
    {
      "dataset": "inventory_critical",
      "description": "موجودی قطعات حیاتی و نقطهٔ سفارش",
      "dimensions": [
        "item"
      ],
      "measures": [
        "current_stock",
        "reorder_point",
        "lead_time_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "purchase_price_variance",
      "description": "انحراف قیمت خرید",
      "formula": "(قیمت واقعی - قیمت برنامه‌ریزی‌شده) / قیمت برنامه‌ریزی‌شده",
      "unit": "درصد",
      "dimensions": [
        "item"
      ]
    },
    {
      "metric": "supplier_on_time",
      "description": "نرخ تحویل به‌موقع",
      "formula": "تحویل‌های به‌موقع / کل تحویل‌ها",
      "unit": "درصد",
      "dimensions": [
        "supplier"
      ]
    }
  ],
  "business_context": [
    "خرید مواد اولیه، قطعات یدکی و مصرفی معدن از تأمین‌کنندگان داخلی و خارجی",
    "قراردادهای بلندمدت و سالانه با تأمین‌کنندگان اصلی",
    "تأمین قطعات حیاتی تجهیزات معدنی با زمان تحویل طولانی"
  ]
}

نقش سازمانی: مدیر انبار و زنجیرهٔ تأمین (warehouse_manager)

درخواست کاربر:
نمای چرخش موجودی سه‌ماهه را به تفکیک دسته بده؛ کدام دسته سرمایهٔ ما را راکد کرده؟ (مدیر انبار و زنجیرهٔ تأمین — توزیع قطعات یدکی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "inventory_levels",
      "description": "موجودی میانگین و مصرف به تفکیک دسته و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "avg_inventory_m_toman",
        "usage_m_toman"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "inventory_turnover",
      "description": "چرخش موجودی",
      "formula": "مصرف دوره / میانگین موجودی",
      "unit": "بار در دوره",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "days_on_hand",
      "description": "روزهای نگهداشت",
      "formula": "میانگین موجودی / مصرف روزانه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی"
  ]
}

